import json,re,sqlite3,gzip,urllib.request,urllib.parse,pathlib
headers={'User-Agent':'nai-v5-studio-personal/1.0'}
slugs=['sex','tag_group:sex_acts','tag_group:sexual_positions']
all_names=set()
for slug in slugs:
    url='https://danbooru.donmai.us/wiki_pages/'+urllib.parse.quote(slug,safe='')+'.json'
    req=urllib.request.Request(url,headers=headers)
    with urllib.request.urlopen(req,timeout=30) as response: page=json.load(response)
    for name in re.findall(r'\[\[([^\]|#]+)', page.get('body','')):
        name=name.strip()
        if name and not name.lower().startswith('tag group:') and name.lower()!='tag groups': all_names.add(name)
def norm(s): return re.sub(r'\s+',' ',s.replace('_',' ').replace('\\(','(').replace('\\)',')').strip().lower())
gz=pathlib.Path('src-tauri/resources/danbooru.sqlite.gz'); tmp=pathlib.Path('.agent/danbooru-sex-measure.sqlite')
with gzip.open(gz,'rb') as src, tmp.open('wb') as dst: dst.write(src.read())
con=sqlite3.connect(tmp); rows=con.execute('select raw,category,count from tags').fetchall(); idx={norm(r):(r,c,n) for r,c,n in rows}
counts=[]
for name in all_names:
    row=idx.get(norm(name))
    if row and row[1]==0: counts.append(int(row[2]))
    elif not row: counts.append(0)
con.close(); tmp.unlink(missing_ok=True)
print('TOTAL='+str(len(counts)))
for t in [100,250,500,750,1000,1500,2000,3000,5000,10000]: print(f'>={t}: '+str(sum(c>=t for c in counts)))
'@; $p=Join-Path $env:TEMP 'nai_measure_sex.py'; Set-Content $p $py -Encoding UTF8; python $p; $code=$LASTEXITCODE; Remove-Item $p -Force -ErrorAction SilentlyContinue; exit $code
